import{_ as t,l as i,o as e,c as s,v as o,p as n,x as r,d,i as E,S as M}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Moore 与 Mealy","description":"","frontmatter":{"title":"Moore 与 Mealy","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/moore-mealy.md","filePath":"cs/moore-mealy.md","lastUpdated":1789023840000}'),m={name:"cs/moore-mealy.md"};function p(c,a,h,A,_,y){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="moore-与-mealy" tabindex="-1">Moore 与 Mealy <a class="header-anchor" href="#moore-与-mealy" aria-label="Permalink to &quot;Moore 与 Mealy&quot;">​</a></h1><div class="epigraph"><p>输出只看现态，则毛刺少、往往晚一拍；输出还看输入，则组合路径穿过控制器，可能更快也更险。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/fsm-control">有限状态机</a>已经写出 \\(\\delta\\) 与 \\(\\lambda\\)，并点了 Moore/Mealy 的差别。本课不重列编码，也不从正则语言另起。缺口是把两种输出接到<strong>关键路径与毛刺</strong>上：后课 CPU 控制器、总线应答，必须选哪一种，不能停在「两种都承认」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Moore：\\(\\lambda:S\\to\\) 输出，输出随状态寄存器，边沿后才变。Mealy：\\(\\lambda:S\\times\\Sigma\\to\\) 输出，输入一变输出就可以变，不必等下一拍。缺口是时序：Mealy 把输入到输出的组合算进<a href="/cs/critical-path">关键路径</a>，并可能把输入毛刺送到输出；Moore 多一拍延迟，输出在周期内稳定（除边沿附近）。</p><p>混合常见：若干位 Moore（使能、选通），若干位 Mealy（提前应答）。本课钉分类，不把状态最小化算法写完。</p><h3 id="mealy-不是「更高级的-fsm」" tabindex="-1">Mealy 不是「更高级的 FSM」 <a class="header-anchor" href="#mealy-不是「更高级的-fsm」" aria-label="Permalink to &quot;Mealy 不是「更高级的 FSM」&quot;">​</a></h3><p>不是表达能力分层。任何 Mealy 可改造成 Moore（加状态、加一拍）。把 Mealy 当更现代，后课会把所有控制做成输入组合，保持时间更容易坏。</p><p><span class="marginnote">Harris 用序列检测对比：Mealy 可在输入到达当拍出「已匹配」。CPU 的 MemRead 等常同步到状态，避免组合读脉冲切到存储器中途。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>同一规格画两张图：Moore 把输出标在圈上，Mealy 标在边上。综合：Moore 输出只接现态译码；Mealy 再与输入门。检查：Mealy 输出是否满足下游建立；是否允许毛刺（纯组合下游 vs 边沿采样）。</p>',11)),(e(),n(M,null,{default:r(()=>[E(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E7%8E%B0%E6%80%81%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%20--%3E%20MOORE%5B%22Moore%EF%BC%9A%E8%BE%93%E5%87%BA%E5%8F%AA%E7%9C%8B%E7%8A%B6%E6%80%81%22%5D%0A%20%20ST%20--%3E%20MEALY%5B%22Mealy%EF%BC%9A%E8%BE%93%E5%87%BA%E7%9C%8B%E7%8A%B6%E6%80%81%E4%B8%8E%E8%BE%93%E5%85%A5%22%5D%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%22%5D%20--%3E%20MEALY%0A%20%20MEALY%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%AE%A1%E6%95%B0%E5%99%A8%E7%89%B9%E4%BE%8B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课多周期控制器：多数拍内控制向量跟状态走（Moore），个别「输入已就绪则当拍转」用 Mealy。计数器输出就是状态本身，是 Moore 的特例。<a href="/cs/setup-hold">建立保持</a>对 Mealy 输出到下游 FF 仍然适用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证两种自动机的形式等价细节，不引入层次状态机、UML。异步 Mealy（无时钟）不在主干。</p><p>后课默认：控制器先按 Moore 画稳，需要当拍响应再局部 Mealy；计数器沿环走，输出即现态。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Moore 输出随状态，稳、常晚一拍。</li><li>Mealy 输出含输入，快、进关键路径、易毛刺。</li><li>表达力可互化；选型是时序与延迟。</li><li>出处：Harris and Harris。</li></ul>',7))])}const f=t(m,[["render",p]]);export{u as __pageData,f as default};
